  sequence of frames, each frame a height-by-width matrix following the
  ``costs`` rules per frame; providing both ``costs`` and
  ``dynamic_costs`` raises ``ValueError``.
- ``reservations`` (``plan``, ``plan_any``, ``plan_batch``,
  ``plan_multi_start``, ``plan_k`` and ``replay``) may be
  omitted, ``None`` or an empty sequence. Otherwise it must be a
  sequence of non-empty coordinate paths; consecutive stays are kept,
  duplicate routes merge and the entry order never affects the result.
- ``trace`` must be a bool; non-bool values raise ``TypeError``.
- ``max_steps`` (``plan``, ``plan_any``, ``plan_batch``,
  ``plan_multi_start``, ``plan_k`` and ``replay``) may be omitted or
  ``None`` (the window disabled). When given it must be a non-negative,
  non-bool integer: other types raise ``TypeError`` and negative values
  raise ``ValueError``. It is validated after every other argument
  (``reservations`` included) and before the search or path judgment;
  in ``plan_batch`` the check precedes every request, so a bad batch
  never produces partial results.
- Type or structure violations raise ``TypeError``; non-positive
  dimensions, out-of-bounds coordinates, endpoints on obstacles, wrong
  matrix shape, or non-positive cell costs raise ``ValueError``.
- Duplicate blocked cells are merged without changing the result.
"""

import heapq
from collections.abc import Iterable, Sequence

__all__ = ["plan", "plan_any", "plan_k", "plan_batch", "plan_agents",
           "plan_multi_start",
           "replay", "resume", "distance_field", "distance_field_any",
           "verify_trace", "verify_any_trace", "verify_batch_trace",
           "verify_agents"]

# Fixed neighbor generation order: +x, -x, +y, -y.
_NEIGHBORS = ((1, 0), (-1, 0), (0, 1), (0, -1))

# Checkpoint format version written by ``snapshot=True`` and required by
# ``resume``; bump whenever the snapshot layout changes.
_SNAPSHOT_VERSION = 1


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_dimension(value, name):
    if not _is_int(value):
        raise TypeError(
            f"{name} must be an int, got {type(value).__name__}"
        )
    if value <= 0:
        raise ValueError(f"{name} must be a positive integer, got {value}")
    return value


def _normalize_point(value, name):
    if isinstance(value, (str, bytes)) or not isinstance(value, Sequence):
        raise TypeError(
            f"{name} must be a sequence of two integers, "
            f"got {type(value).__name__}"
        )
    if len(value) != 2:
        raise TypeError(
            f"{name} must contain exactly two coordinates, got {len(value)}"
        )
    x, y = value[0], value[1]
    if not _is_int(x) or not _is_int(y):
        raise TypeError(f"{name} coordinates must be integers, got {value!r}")
    return (x, y)


def _check_bounds(point, width, height, name):
    x, y = point
    if not (0 <= x < width and 0 <= y < height):
        raise ValueError(
            f"{name} {point} is outside the {width}x{height} grid"
        )


def _normalize_blocked(blocked, width, height):
    if isinstance(blocked, (str, bytes)) or not isinstance(blocked, Iterable):
        raise TypeError(
            f"blocked must be an iterable of grid coordinates, "
            f"got {type(blocked).__name__}"
        )
    cells = set()
    for index, item in enumerate(blocked):
        name = f"blocked[{index}]"
        point = _normalize_point(item, name)
        _check_bounds(point, width, height, name)
        cells.add(point)  # duplicates merge into one cell
    return cells


def _normalize_costs(costs, width, height):
    if costs is None:
        return None  # unit step cost
    if isinstance(costs, (str, bytes)) or not isinstance(costs, Sequence):
        raise TypeError(
            f"costs must be a height-by-width matrix of positive integers, "
            f"got {type(costs).__name__}"
        )
    if len(costs) != height:
        raise ValueError(
            f"costs must have exactly {height} rows, got {len(costs)}"
        )
    rows = []
    for y, row in enumerate(costs):
        if isinstance(row, (str, bytes)) or not isinstance(row, Sequence):
            raise TypeError(
                f"costs[{y}] must be a sequence of {width} positive "
                f"integers, got {type(row).__name__}"
            )
        if len(row) != width:
            raise ValueError(
                f"costs[{y}] must have exactly {width} cells, "
                f"got {len(row)}"
            )
        parsed = []
        for x, cell in enumerate(row):
            if not _is_int(cell):
                raise TypeError(
                    f"costs[{y}][{x}] must be an int, "
                    f"got {type(cell).__name__}"
                )
            if cell <= 0:
                raise ValueError(
                    f"costs[{y}][{x}] must be a positive integer, "
                    f"got {cell}"
                )
            parsed.append(cell)
        rows.append(tuple(parsed))
    return tuple(rows)


def _normalize_dynamic_costs(dynamic_costs, width, height):
    # ``dynamic_costs`` is the time-varying counterpart of ``costs``: a
    # sequence of height-by-width positive integer matrices, one per time
    # frame. ``None`` or an empty sequence disables it (equivalent to not
    # provided). The outer value and every frame must be sequences
    # (strings/bytes and other non-sequences raise ``TypeError``); a frame

def _normalize_record_entry(item, name):
    # A recorded trajectory state inside a ``verify_trace`` record: a
    # sequence of two or three integers (the mode check happens later,
    # once the whole structure is known to be well-formed).
    if isinstance(item, (str, bytes)) or not isinstance(item, Sequence):
        raise TypeError(
            f"{name} must be a sequence of two or three integers, "
            f"got {type(item).__name__}"
        )
    if len(item) not in (2, 3):
        raise TypeError(
            f"{name} must contain two or three integers, got {len(item)}"
        )
    if not all(_is_int(value) for value in item):
        raise TypeError(f"{name} must contain only integers, got {item!r}")
    return tuple(item)


def _restore_record(record, dynamic, width, height, unique_static=True):
    # Validate a saved planning record for ``verify_trace`` (and, with
    # ``unique_static=False``, ``verify_any_trace``) and normalize its
    # coordinates to tuples. A record that is not an object, lacks a
    # required field, has a wrongly typed field or a wrongly shaped
    # trajectory entry raises ``TypeError``; an out-of-bounds coordinate,
    # a trajectory entry inconsistent with the static/dynamic mode the
    # arguments select (a triple in static mode, a pair in dynamic mode,
    # a negative time, or--only when ``unique_static`` is set--a state
    # recorded twice by a static search that closes each cell at most
    # once) or an invalid checkpoint structure raises ``ValueError``.
    # Everything is decided here, before the audit search starts. The
    # record itself is never modified.
    #
    # ``plan_any``'s search is history sensitive even without timed
    # frames: the same coordinate reached through a different path is a
    # distinct route-tree node, so its static trace may legitimately
    # record a coordinate more than once (``verify_any_trace`` therefore
    # passes ``unique_static=False``). ``plan``'s static search closes
    # every cell at most once, so a repeated pair is a malformed record.
    if not isinstance(record, dict):
        raise TypeError(
            f"record must be a planning result object, "
            f"got {type(record).__name__}"
        )
    for key in ("path", "cost", "expanded", "expanded_nodes"):
        if key not in record:
            raise TypeError(f"record is missing required field {key!r}")
    raw_path = record["path"]
    if raw_path is None:
        path = None
    else:
        if (isinstance(raw_path, (str, bytes))
                or not isinstance(raw_path, Sequence)):
            raise TypeError(
                f"record path must be null or a sequence of grid "
                f"coordinates, got {type(raw_path).__name__}"
            )
        path = []
        for index, item in enumerate(raw_path):
            name = f"record path[{index}]"
            point = _normalize_point(item, name)
            _check_bounds(point, width, height, name)
            path.append(point)
    cost = record["cost"]
    if cost is not None and not _is_int(cost):
        raise TypeError(
            f"record cost must be null or an int, "
            f"got {type(cost).__name__}"
        )
    expanded = record["expanded"]
    if not _is_int(expanded):
        raise TypeError(
            f"record expanded must be an int, "
            f"got {type(expanded).__name__}"
        )
    raw_nodes = record["expanded_nodes"]
    if (isinstance(raw_nodes, (str, bytes))
            or not isinstance(raw_nodes, Sequence)):
        raise TypeError(
            f"record expanded_nodes must be a sequence of recorded "
            f"states, got {type(raw_nodes).__name__}"
        )
    arity = 3 if dynamic else 2
    nodes = []
    seen = set()
    for index, item in enumerate(raw_nodes):
        name = f"record expanded_nodes[{index}]"
        entry = _normalize_record_entry(item, name)
        if len(entry) != arity:
            raise ValueError(
                f"{name} records {len(entry)} values but the "
                f"{'dynamic' if dynamic else 'static'} mode records "
                f"{arity}"
            )
        cell = (entry[0], entry[1])
        _check_bounds(cell, width, height, name)
        if dynamic:
            if entry[2] < 0:
                raise ValueError(
                    f"{name} has a negative time {entry[2]}"
                )
        elif unique_static:
            if entry in seen:
                raise ValueError(
                    f"{name} records a state twice"
                )
            seen.add(entry)
        nodes.append(entry)
    status = record.get("status")
    if status is not None and not isinstance(status, str):
        raise TypeError(
            f"record status must be a string, "
            f"got {type(status).__name__}"
        )
    checkpoint = record.get("checkpoint")
    if checkpoint is not None:
        try:
            _restore_checkpoint(checkpoint)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"record checkpoint is not a valid snapshot: {exc}"
            ) from exc
    return {
        "path": path,
        "cost": cost,
        "expanded": expanded,
        "expanded_nodes": nodes,
        "status": status,
        "checkpoint": checkpoint,
    }


def _restore_batch_record(record, dynamic, width, height, expected_count):
    # Validate a saved ``plan_batch`` record for ``verify_batch_trace``
    # and normalize every entry's coordinates to tuples. The record must
    # be an object carrying ``results``: a sequence with exactly one
    # entry per normalized request, each a valid ``plan`` record as
    # ``_restore_record`` defines it (a static ``plan`` search closes
    # every cell at most once, so ``unique_static`` stays set). A record
    # that is not an object, lacks ``results``, has a wrongly typed
    # ``results`` or entry field, or a wrongly shaped trajectory entry
    # raises ``TypeError``; a results length that differs from the
    # request count, an out-of-bounds coordinate, a trajectory entry
    # inconsistent with the static/dynamic mode the arguments select, or
    # an invalid checkpoint structure raises ``ValueError``. Everything
    # is decided here, before any audit search starts, and the record
    # itself is never modified.
    if not isinstance(record, dict):
        raise TypeError(
            f"record must be a batch result object, "
            f"got {type(record).__name__}"
        )
    if "results" not in record:
        raise TypeError("record is missing required field 'results'")
    raw_results = record["results"]
    if (isinstance(raw_results, (str, bytes))
            or not isinstance(raw_results, Sequence)):
        raise TypeError(
            f"record results must be a sequence of planning result "
            f"objects, got {type(raw_results).__name__}"
        )
    if len(raw_results) != expected_count:
        raise ValueError(
            f"record results must contain exactly {expected_count} "
            f"entries, got {len(raw_results)}"
        )
    saved = []
    for index, item in enumerate(raw_results):
        try:
            saved.append(_restore_record(item, dynamic, width, height))
        except (TypeError, ValueError) as exc:
            raise type(exc)(
                f"record results[{index}] is not a valid planning "
                f"record: {exc}"
            ) from exc
    return saved


def _restore_agents_record(record, dynamic, width, height, request_count):
    # Validate a saved ``plan_agents`` record for ``verify_agents`` and
    # normalize every coordinate to tuples. The record must be an object
    # carrying ``status``, ``results`` and ``expanded``: a missing field,
    # a wrongly typed field or a wrongly shaped trajectory entry raises
    # ``TypeError``. ``status`` selects the required shape: ``"found"``
    # demands exactly one result per request, while ``"unreachable"``
    # also demands a ``failed_index`` field and exactly
    # ``failed_index + 1`` results; an unknown status string, an
    # out-of-range ``failed_index`` or a result count that does not
    # match the status raises ``ValueError``. Every entry follows
    # ``verify_trace``'s record rules with the arity of the search that
    # produced it: the first agent records coordinate pairs in static
    # mode, and every later agent records ``(x, y, t)`` triples because
    # its predecessors' routes already make its search time-expanded.
    # Everything is decided here, before the audit search starts, and
    # the record itself is never modified.
    if not isinstance(record, dict):
        raise TypeError(
            f"record must be a plan_agents result object, "
            f"got {type(record).__name__}"
        )
    for key in ("status", "results", "expanded"):
        if key not in record:
            raise TypeError(f"record is missing required field {key!r}")
    status = record["status"]
    if not isinstance(status, str):
        raise TypeError(
            f"record status must be a string, "
            f"got {type(status).__name__}"
        )
    if status not in ("found", "unreachable"):
        raise ValueError(
            f"record status must be 'found' or 'unreachable', "
            f"got {status!r}"
        )
    expanded = record["expanded"]
    if not _is_int(expanded):
        raise TypeError(
            f"record expanded must be an int, "
            f"got {type(expanded).__name__}"
        )
    raw_results = record["results"]
    if (isinstance(raw_results, (str, bytes))
            or not isinstance(raw_results, Sequence)):
        raise TypeError(
            f"record results must be a sequence of planning result "
            f"objects, got {type(raw_results).__name__}"
        )
    if status == "found":
        failed_index = None
        expected = request_count
    else:
        if "failed_index" not in record:
            raise TypeError(
                "record is missing required field 'failed_index'"
            )
        failed_index = record["failed_index"]
        if not _is_int(failed_index):
            raise TypeError(
                f"record failed_index must be an int, "
                f"got {type(failed_index).__name__}"
            )
        if not 0 <= failed_index < request_count:
            raise ValueError(
                f"record failed_index must be between 0 and "
                f"{request_count - 1}, got {failed_index}"
            )
        expected = failed_index + 1
    if len(raw_results) != expected:
        raise ValueError(
            f"record results must contain exactly {expected} "
            f"entries, got {len(raw_results)}"
        )
    saved = []
    for index, item in enumerate(raw_results):
        # The first agent searches the plain grid; every later agent's
        # search is time-expanded by its predecessors' routes, so its
        # trace always records triples.
        try:
            saved.append(_restore_record(
                item, dynamic or index > 0, width, height
            ))
        except (TypeError, ValueError) as exc:
            raise type(exc)(
                f"record results[{index}] is not a valid planning "
                f"record: {exc}"
            ) from exc
    return {
        "status": status,
        "failed_index": failed_index,
        "results": saved,
        "expanded": expanded,
    }


def _first_difference(saved, actual):
    # The zero-based index of the first position where a recorded
    # sequence differs from the recomputed one, or ``None`` when they
    # are equal. A null side only equals another null side; a null side
    # against a sequence diverges at its first position.
    if saved is None or actual is None:
        return None if saved is None and actual is None else 0
    for index, (left, right) in enumerate(zip(saved, actual)):
        if left != right:
            return index
    if len(saved) != len(actual):
        return min(len(saved), len(actual))
    return None


def _canonical_json(value):
    # Recursively rewrite tuples as lists so a record that survived a

def _canonical_json(value):
    # Recursively rewrite tuples as lists so a record that survived a
    # JSON round trip compares equal to the freshly computed value.
    if isinstance(value, dict):
        return {key: _canonical_json(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_canonical_json(item) for item in value]
    return value


def verify_trace(width, height, blocked, start, goal, record, costs=None,
                 dynamic_blocked=None, max_expanded=None, snapshot=False,
                 max_cost=None, allow_wait=False, dynamic_costs=None,
                 reservations=None, max_steps=None):
    # --- Validation: ``plan``'s public checks in their usual order     ---
    # --- (only the never-present ``trace`` flag is skipped; the audit  ---
    # --- always recomputes with the trace on). The record is inspected  ---
    # --- only after every grid and constraint check has run, so a      ---
    # --- missing or malformed record never skips a grid error.         ---
    width = _validate_dimension(width, "width")
    height = _validate_dimension(height, "height")
    start = _normalize_point(start, "start")
    goal = _normalize_point(goal, "goal")
    _check_bounds(start, width, height, "start")
    _check_bounds(goal, width, height, "goal")
    obstacles = _normalize_blocked(blocked, width, height)
    if start in obstacles:
        raise ValueError(f"start {start} lies on a blocked cell")
    if goal in obstacles:
        raise ValueError(f"goal {goal} lies on a blocked cell")
    costs = _normalize_costs(costs, width, height)
    frames = _normalize_dynamic_blocked(dynamic_blocked, width, height)
    if frames is not None and start in frames[0]:
        raise ValueError(
            f"start {start} is blocked at frame 0"
        )
    # The waiting flag, the budget, the snapshot flag, the cost limit,
    # the time-varying cost frames and the reserved routes keep exactly
    # ``plan``'s positions; every check is decided before the record is
    # inspected and before the audit search starts.
    _validate_allow_wait(allow_wait)
    _validate_budget(max_expanded)
    _validate_snapshot_flag(snapshot)
    _validate_max_cost(max_cost)
    cost_frames = _normalize_dynamic_costs(dynamic_costs, width, height)
    if cost_frames is not None and costs is not None:
        raise ValueError(
            "costs and dynamic_costs cannot both be provided"
        )
    reservation_paths = _normalize_reservations(
        reservations, width, height, obstacles
    )
    _validate_max_steps(max_steps)
    dynamic = (frames is not None or cost_frames is not None
               or reservation_paths is not None)
    saved = _restore_record(record, dynamic, width, height)
    # --- Audit: recompute the deterministic result with the trace on   ---
    # --- and compare field by field in the fixed order. Nothing of the ---
    # --- recomputation leaks into the report.                          ---
    if dynamic:
        result = _search_dynamic(
            width, height, obstacles, frames, start, goal, costs, True,
            max_expanded, max_cost, snapshot, allow_wait,
            cost_frames=cost_frames, reservations=reservation_paths,
            max_steps=max_steps
        )
    else:
        result = _search_static(
            width, height, obstacles, start, goal, costs, True,
            max_expanded, max_cost, snapshot, allow_wait,
            max_steps=max_steps
        )
    index = _first_difference(saved["path"], result["path"])
    if index is not None:
        return {"valid": False, "mismatch": "path", "index": index}
    if saved["cost"] != result["cost"]:
        return {"valid": False, "mismatch": "cost", "index": None}
    if saved["expanded"] != result["expanded"]:
        return {"valid": False, "mismatch": "expanded", "index": None}
    index = _first_difference(saved["expanded_nodes"],
                              result["expanded_nodes"])
    if index is not None:
        return {"valid": False, "mismatch": "expanded_nodes",
                "index": index}
    if "status" in result and saved["status"] != result["status"]:
        return {"valid": False, "mismatch": "status", "index": None}
    if ("checkpoint" in result
            and _canonical_json(saved["checkpoint"])
            != _canonical_json(result["checkpoint"])):
        return {"valid": False, "mismatch": "checkpoint", "index": None}
    return {"valid": True, "mismatch": None, "index": None}


def verify_any_trace(width, height, blocked, start, goals, record,
                     costs=None, dynamic_blocked=None, max_expanded=None,
                     snapshot=False, max_cost=None, allow_wait=False,
                     dynamic_costs=None, reservations=None, max_steps=None):
    # --- Validation: ``plan_any``'s public checks in their exact order  ---
    # --- (``goals`` takes ``goal``'s position; only the never-present   ---
    # --- ``trace`` flag is skipped, since the audit always recomputes   ---
    # --- with the trace on). The record is inspected only after every   ---
    # --- grid and constraint check has run, so a missing or malformed   ---
    # --- record never skips a grid or goals error and a failed check    ---
    # --- never starts a search or returns a partial report.             ---
    width = _validate_dimension(width, "width")
    height = _validate_dimension(height, "height")
    start = _normalize_point(start, "start")
    goal_points = _normalize_goals(goals)
    _check_bounds(start, width, height, "start")
    for point in goal_points:
        _check_bounds(point, width, height, "goal")
    obstacles = _normalize_blocked(blocked, width, height)
    if start in obstacles:
        raise ValueError(f"start {start} lies on a blocked cell")
    for point in goal_points:
        if point in obstacles:
            raise ValueError(f"goal {point} lies on a blocked cell")
    costs = _normalize_costs(costs, width, height)
    frames = _normalize_dynamic_blocked(dynamic_blocked, width, height)
    if frames is not None and start in frames[0]:
        raise ValueError(
            f"start {start} is blocked at frame 0"
        )
    # The waiting flag, the budget, the snapshot flag, the cost limit,
    # the time-varying cost frames and the reserved routes keep exactly
    # ``plan_any``'s positions; every check is decided before the record
    # is inspected and before the audit search starts.
    _validate_allow_wait(allow_wait)
    _validate_budget(max_expanded)
    _validate_snapshot_flag(snapshot)
    _validate_max_cost(max_cost)
    cost_frames = _normalize_dynamic_costs(dynamic_costs, width, height)
    if cost_frames is not None and costs is not None:
        raise ValueError(
            "costs and dynamic_costs cannot both be provided"
        )
    reservation_paths = _normalize_reservations(
        reservations, width, height, obstacles
    )
    _validate_max_steps(max_steps)
    dynamic = (frames is not None or cost_frames is not None
               or reservation_paths is not None)
    # ``plan_any``'s route-tree search closes a coordinate through each
    # distinct history even in static mode, so a repeated pair in the
    # recorded trace is not a malformed record (unlike ``verify_trace``).
    saved = _restore_record(record, dynamic, width, height,
                            unique_static=False)
    # --- Audit: recompute the deterministic multi-goal result with the  ---
    # --- trace on and compare field by field in the fixed order. Lists  ---
    # --- and tuples compare equal (JSON round trips), extra record      ---
    # --- fields are ignored, and nothing of the recomputation or the    ---
    # --- comparison modifies the record.                                ---
    result = _search_any(
        width, height, obstacles, frames, start, goal_points, costs, True,
        max_expanded, max_cost, snapshot, allow_wait,
        cost_frames=cost_frames, reservations=reservation_paths,
        max_steps=max_steps
    )
    index = _first_difference(saved["path"], result["path"])
    if index is not None:
        return {"valid": False, "mismatch": "path", "index": index}
    if saved["cost"] != result["cost"]:
        return {"valid": False, "mismatch": "cost", "index": None}
    if saved["expanded"] != result["expanded"]:
        return {"valid": False, "mismatch": "expanded", "index": None}
    index = _first_difference(saved["expanded_nodes"],
                              result["expanded_nodes"])
    if index is not None:
        return {"valid": False, "mismatch": "expanded_nodes",
                "index": index}
    if "status" in result and saved["status"] != result["status"]:
        return {"valid": False, "mismatch": "status", "index": None}
    if ("checkpoint" in result
            and _canonical_json(saved["checkpoint"])
            != _canonical_json(result["checkpoint"])):
        return {"valid": False, "mismatch": "checkpoint", "index": None}
    return {"valid": True, "mismatch": None, "index": None}


def verify_batch_trace(width, height, blocked, requests, record, costs=None,
                       dynamic_blocked=None, max_expanded=None, snapshot=False,
                       max_cost=None, allow_wait=False, dynamic_costs=None,
                       reservations=None, max_steps=None):
    # --- Validation: ``plan_batch``'s public checks in their exact    ---
    # --- order (only the never-present ``trace`` flag is skipped; the ---
    # --- audit always recomputes with the trace on). The record is    ---
    # --- inspected only after every shared and per-request check has  ---
    # --- run, so a missing or malformed record never skips a grid or  ---
    # --- requests error and a failed check never starts a search.     ---
    width = _validate_dimension(width, "width")
    height = _validate_dimension(height, "height")
    pairs = _normalize_requests(requests)
    for index, (start, goal) in enumerate(pairs):
